};
const defaultSessions = [
  ["010.jpg","BBC Masterclass","15 AUG 2016","Improve your English with this week's BBC Learning English Masterclass."],
  ["020.png","News Review","16 AUG 2016","Learn useful vocabulary and hear the latest story in News Review."]
];
let selectedUnit = 1;
let activeTab = "sessions";
const grid = document.getElementById("unitGrid");
const labels = document.getElementById("unitLabels");
for (let i=1;i<=30;i++) {
  const cell = document.createElement("button");
  cell.className = "unit-cell btn" + (i===1 ? " selected" : "");
  cell.setAttribute("aria-label","Select unit "+i);
  cell.onclick = () => selectUnit(i);
  grid.appendChild(cell);
  const label = document.createElement("button");
  label.className = "btn";
  label.textContent = i;
  label.onclick = () => selectUnit(i);
  labels.appendChild(label);
}
function selectUnit(n) {
  selectedUnit = n;
  document.getElementById("unitNumber").textContent = n;
  document.getElementById("unitName").textContent = "Unit " + n + ": Towards advanced";
  document.getElementById("unitSubtitle").textContent = (unitData[n] || {}).subtitle || "Grammar, news, vocabulary and pronunciation";
  [...grid.children].forEach((el,i)=>el.classList.toggle("selected",i===n-1));
  render();
}
document.getElementById("toggleSelector").addEventListener("click",()=>{
  document.getElementById("course").classList.toggle("selector-hidden");
  const closed = document.getElementById("course").classList.contains("selector-hidden");
  document.getElementById("toggleSelector").innerHTML = closed ? "Open unit selector&nbsp; ∨" : "Close unit selector&nbsp; ∧";
});
document.querySelectorAll(".tab-row button").forEach(button=>{
  button.addEventListener("click",()=>{
    activeTab = button.dataset.tab;
    document.querySelectorAll(".tab-row button").forEach(b=>b.classList.toggle("active",b===button));
    render();
  });
});
function sessionMarkup(item,index) {
  const title = index ? "Session 2" : "Session 1";
  return `<article class="session">
    <img class="session-image" src="__PLACEHOLDER_ASSETS_BASE_DIR__/${item[0]}" width="315" height="190" alt="">
    <div class="session-copy">
      <div class="session-heading">${title}<span class="activity">1 ACTIVITY</span></div>
      <div class="session-kind">${item[1]}</div>
      <div class="date">${item[2]}</div>
      <div class="description">${item[3]}</div>
    </div>
  </article>`;
}
function sidebar(grammar) {
  return `<aside>
    <div class="side-box"><a class="btn" onclick="setTab('sessions')">View sessions in this unit &gt;</a></div>
    <div class="side-box"><h3>Session ${grammar ? "Vocabulary" : "Grammar"}</h3><a class="btn">${grammar ? "Practise this vocabulary" : "Practise this grammar"} &gt;</a></div>
    <div class="side-box download"><span>DOWNLOAD CENTRE</span><a class="btn">Latest course content</a></div>
  </aside>`;
}
function vocabView() {
  return `<div class="reference-view">
    <div class="reference-main">
      <h1>Vocabulary Reference</h1>
      <h2>Session 2 - News Review</h2>
      <div class="vocab-entry"><strong>an upset</strong>when someone beats the team or player that was expected to win</div>
      <div class="vocab-entry"><strong>pull something off</strong>to succeed in doing something that is difficult</div>
      <div class="vocab-entry"><strong>egg somebody on</strong>encourage someone or urge someone to do something (especially something they shouldn't do)</div>
      <div class="vocab-entry"><strong>pandemonium</strong>a situation in which there is a lot of noise or craziness because people are excited, angry, or frightened</div>
      <h2>Session 3 - Lingohack</h2>
      <div class="vocab-entry"><strong>medal tally</strong>number of medals won</div>
      <div class="vocab-entry"><strong>feeds on</strong>eats, consumes (especially for animals)</div>
      <div class="vocab-entry"><strong>cheating</strong>breaking the rules of a competition</div>
      <h2>Session 4 - Pygmalion: 8 uses of 'round'</h2>
      <div class="vocab-entry"><strong>driving him around the bend (C2)</strong>making him very annoyed</div>
      <div class="vocab-entry"><strong>comes round (C2)</strong>begins to accept something previously rejected</div>
      <div class="vocab-entry"><strong>round and round (B2)</strong>moving in a circular direction</div>
      <div class="vocab-entry"><strong>round the clock (C1)</strong>all day and all night</div>
      <div class="vocab-entry"><strong>round (A2)</strong>on all sides (of something)</div>
      <div class="vocab-entry"><strong>goes round to (A2)</strong>visits</div>
      <div class="vocab-entry"><strong>in a roundabout kind of way (C2)</strong>more or less; sort of</div>
      <div class="vocab-entry"><strong>round off (B2)</strong>finish; complete (something)</div>
      <button class="practice btn">Practise Vocabulary&nbsp; ›</button>
    </div>${sidebar(false)}
  </div>`;
}
function grammarView() {
  return `<div class="reference-view">
    <div class="reference-main">
      <h1>Grammar Reference</h1>
      <h2>Conditionals review</h2>
      <h3>Meaning and use</h3>
      <p>Conditional sentences express a connection between two actions or states. One thing happens because of another. These connections can be general, specific, likely, unlikely, real or imagined.</p>
      <p>Although there are quite a few different ways of forming conditional sentences there are common patterns known as zero, first, second and third conditionals.</p>
      <h3>Zero conditionals</h3>
      <p>Used to refer to general truths, scientific facts and the predictable results of particular actions. One thing happens and because of this something else happens. In zero conditionals <em>if</em> and <em>when</em> have the same meaning.</p>
      <p><em>If you heat water enough, it boils.</em></p>
      <h3>First conditionals</h3>
      <p>We use the first conditional to talk about a possible situation in the future and its likely result.</p>
      <button class="practice btn">Practise Grammar&nbsp; ›</button>
    </div>${sidebar(true)}
  </div>`;
}
function setTab(tab) {
  activeTab = tab;
  document.querySelectorAll(".tab-row button").forEach(b=>b.classList.toggle("active",b.dataset.tab===tab));
  render();
}
function render() {
  const main = document.getElementById("mainArea");
  if (activeTab === "vocabulary") { main.innerHTML = vocabView(); return; }
  if (activeTab === "grammar") { main.innerHTML = grammarView(); return; }
  const items = (unitData[selectedUnit] || {}).sessions || defaultSessions;
  main.innerHTML = `<div class="sessions-view">${items.map(sessionMarkup).join("")}</div>`;
}
render();
</script>
